// A dozen county regulars have their own routines, voices, and useful little leads.
const locals=[
 {name:'Marlowe Bell',job:'Retired postmaster',mark:'M',x:3,z:4,skin:0xc98968,hair:0x72715f,coat:0x71806b,lead:0,nick:'Marlowe',lines:['You look like you’re trying to remember a place you’ve never been. Happens here. Start with Juniper Row; the porches keep better records than the courthouse.','Mrs. Bell at the corner still puts a saucer of milk out for the carrier’s dog. Has for forty years. Some habits outlast the people who start them.','If the creek is quiet, you can hear the school bell from here. It hasn’t rung in a long while.']},
 {name:'Nell Okafor',job:'Market keeper',mark:'N',x:-40,z:24,skin:0x885a43,hair:0x28251f,coat:0xb7794f,lead:9,nick:'Nell',lines:['The peaches are finally sweet. The sign says forty cents, but don’t you dare pay it; that chalkboard hasn’t been right since 1972.','Old Mr. Dwyer comes in every Thursday for coffee and one pear. He never buys two. Never says why.','If you’re following the rail line, ask around about Northline Works. The whistles stopped, but the night shift never quite did.']},
 {name:'Ruthie Vale',job:'School caretaker',mark:'R',x:-37,z:4,skin:0xe0b28a,hair:0xaaa18b,coat:0x596d76,lead:3,nick:'Ruthie',lines:['The mural out back was painted by the graduating class of ’68. Every face in it belongs to someone who still lives within walking distance.','The clock is stopped, not broken. I wind it on the first day of every school year anyway.','A child once left a drawing in the library basement: this town, but with one extra road. I never found that road.']},
 {name:'Dr. Elias Finch',job:'County physician',mark:'E',x:-8,z:-48,skin:0xd9a77f,hair:0x554940,coat:0xb2b4a1,lead:4,nick:'Dr. Finch',lines:['The east wing stays lit because people sleep better when they see a light on. Sometimes that’s the whole of medicine.','A woman in a yellow raincoat used to visit every Wednesday. No chart, no appointment. We never learned her name.','There’s a clinic garden two blocks east. Go there when the day gets too loud; the swallow weathervane points toward the quiet.']},
 {name:'June Sato',job:'Garden volunteer',mark:'J',x:39,z:-47,skin:0xe6bc9a,hair:0x292823,coat:0x75876a,lead:5,nick:'June',lines:['These herbs came from the clinic garden. The rosemary has survived three winters and one very determined groundskeeper.','The weather vane points due north only when nobody is watching it. I’m not joking. Ask anyone who works nights.','If you see a light in the east hospital wing, wave. Someone always waves back.']},
 {name:'Deputy Cal Mercer',job:'Night dispatcher',mark:'C',x:69,z:-52,skin:0xb87c5d,hair:0x463a34,coat:0x586b72,lead:6,nick:'Cal',lines:['Dispatch gets a call every night at 3:10. Nobody speaks. We stopped sending a car after the seventh year.','If you hear the fire bell, don’t worry. Engine House rings it for the old dog’s birthday. The dog’s been gone a decade.','The oldest names in our ledgers all point west, toward Blackpine. Nobody can tell me why.']},
 {name:'Ollie Finch',job:'Volunteer firefighter',mark:'O',x:74,z:-21,skin:0xd6a078,hair:0x44342d,coat:0xa75545,lead:7,nick:'Ollie',lines:['The engine still starts on the first crank. We take it around the block on Founders’ Day. The block gets smaller every year.','A brass bell rings at 3:10, even when the station’s empty. I’ve checked the clapper myself.','The Lantern makes a pie called “the last train.” Nobody knows what’s in it. Nobody asks.']},
 {name:'Bea Larkin',job:'Supper-club pianist',mark:'B',x:2,z:27,skin:0xc58b71,hair:0x382a29,coat:0x8e6873,lead:10,nick:'Bea',lines:['The piano has one key that plays a little late. I leave it in. The room sounds lonely without it.','There’s a booth at the back that stays reserved, always. The name card is blank. The coffee goes cold by midnight.','If you want a room for the night, Solstice has one with a view of a perfectly ordinary wall. Take room eight if you like a mystery.']},
 {name:'Mateo Reyes',job:'Motel caretaker',mark:'M',x:39,z:27,skin:0xb87854,hair:0x302722,coat:0x74818a,lead:11,nick:'Mateo',lines:['Room eight’s key is heavier than the others. I’ve weighed it. It’s the same key; it just feels that way in your hand.','The guestbook has a signature for every summer since 1958. Same name, same handwriting. The ink changes.','Take the north road past the chapel and you’ll find a hill where the flowers never wilt. I bring fresh ones every Sunday.']},
 {name:'Sister Agnes',job:'Keeper of St. Oran’s',mark:'A',x:70,z:5,skin:0xe1b89a,hair:0xe4ddca,coat:0xb9ae91,lead:12,nick:'Sister Agnes',lines:['The bell’s a little flat. It has been for generations. The birds don’t mind; they sing along in a different key.','I leave the side door unlocked in daylight. Someone always needs a place to sit and be quiet.','A family brings wildflowers to Hollow Hill each week. I’ve never seen who. The flowers arrive before sunrise.']},
 {name:'Wes Dwyer',job:'Railway night watchman',mark:'W',x:70,z:57,skin:0x9a654c,hair:0x50443a,coat:0x68735e,lead:14,nick:'Wes',lines:['I hear a train pass at 2:17. There hasn’t been a train on this spur since the mill closed. The sound comes from under the dock.','The clock at the paper mill is right twice a day. It’s stopped at 6:42 since the night of the flood.','If you find yourself under the town, follow the water. Not the footsteps. The water.']},
 {name:'Ivy Moss',job:'County librarian',mark:'I',x:-8,z:59,skin:0xe3bd98,hair:0x65534a,coat:0x81759a,lead:16,nick:'Ivy',lines:['The basement index has a drawer full of places that aren’t there anymore. Somehow the drawer keeps getting fuller.','A book was returned this morning that I never checked out. Inside the cover, someone wrote your name.','There’s an old road on the courthouse map. Walk west from the creek and the pines will tell you where it used to be.']}
];
function makeLocal(local){const root=new THREE.Group();root.position.set(local.x,0,local.z);scene.add(root);const figure=new THREE.Group();root.add(figure);
 const skin=mat(local.skin),hair=mat(local.hair),coat=mat(local.coat),trousers=mat(local.trousers||0x494b43),shoe=mat(0x302e29),eye=mat(0x282d29),accent=mat(local.accent||0xe1c48c);
 const head=new THREE.Mesh(new THREE.SphereGeometry(.225,12,10),skin);head.position.y=1.69;head.castShadow=true;figure.add(head);
 const torso=cyl(figure,0,1.08,0,.24,.31,.78,coat,10);torso.rotation.z=-.035;
 const hips=cyl(figure,0,.66,0,.23,.22,.21,trousers,10);
 for(const side of [-1,1]){const leg=cyl(figure,side*.115,.34,0,.09,.105,.52,trousers,8);leg.position.z=side*.015;const foot=box(figure,side*.12,.09,.075,.17,.13,.31,shoe,false);const arm=cyl(figure,side*.32,1.1,0,.085,.105,.62,coat,8);arm.rotation.z=side*-.12;const hand=new THREE.Mesh(new THREE.SphereGeometry(.09,8,7),skin);hand.position.set(side*.34,.77,.015);figure.add(hand);const eyeDot=new THREE.Mesh(new THREE.SphereGeometry(.022,6,6),eye);eyeDot.position.set(side*.082,1.72,.204);figure.add(eyeDot)}
 const cap=new THREE.Mesh(new THREE.SphereGeometry(.23,10,7,0,Math.PI*2,0,Math.PI*.52),hair);cap.position.set(0,1.83,-.015);cap.scale.set(1.02,.85,1);figure.add(cap);
 for(let k=0;k<3;k++)box(figure,0,1.24-k*.1,.245,.035,.035,.018,accent,false);
 const nose=new THREE.Mesh(new THREE.SphereGeometry(.036,6,6),skin);nose.position.set(0,1.665,.218);figure.add(nose);
 if(local.job.includes('physician')){const badge=box(figure,.15,1.23,.246,.075,.09,.02,white,false);badge.rotation.z=.12}
 if(local.job.includes('firefighter')){const hat=new THREE.Mesh(new THREE.SphereGeometry(.25,10,6,0,Math.PI*2,0,Math.PI/2),mat(0xb94f3d));hat.position.y=1.91;figure.add(hat);box(figure,0,1.82,.03,.43,.045,.32,mat(0xb94f3d),false)}
 root.userData.figure=figure;root.userData.local=local;root.userData.step=rand()*6.28;root.userData.anchor={x:local.x,z:local.z};root.userData.goal=null;return root}
const localActors=locals.map(makeLocal);
// Player, first-person camera and movement state.
const player={x:5,z:9};

