const readSet=key=>{try{return new Set(JSON.parse(localStorage.getItem(key)||'[]'))}catch{return new Set()}};
const found=readSet('elsewhere-notes'),met=readSet('elsewhere-locals'),leads=readSet('elsewhere-leads');let localVisits={};try{localVisits=JSON.parse(localStorage.getItem('elsewhere-local-visits')||'{}')}catch{}
const countEl=document.querySelector('#count'),progressEl=document.querySelector('#progress'),objective=document.querySelector('#objective'),grid=document.querySelector('#mapGrid'),localsGrid=document.querySelector('#localsGrid'),localCount=document.querySelector('#localCount');
function paintProgress(){countEl.textContent=`${found.size} / ${sites.length}`;progressEl.style.width=`${found.size/sites.length*100}%`;objective.innerHTML=found.size===sites.length?'<b>Atlas complete.</b> Every corner of the county is yours.':`Discover <b>${sites.length-found.size}</b> more place${sites.length-found.size===1?'':'s'} to complete your atlas.`;localCount.textContent=`${met.size} / ${locals.length}`;grid.innerHTML='';for(let i=0;i<sites.length;i++){const s=sites[i],known=found.has(i)||leads.has(i),entry=document.createElement('div');entry.className='map-item'+(found.has(i)?' found':leads.has(i)?' found lead':'');entry.innerHTML=`<i>${found.has(i)?s.icon:leads.has(i)?'↗':'·'}</i><span>${known?s.name:'Undiscovered place'}</span>`;grid.append(entry)}localsGrid.innerHTML='';for(let i=0;i<locals.length;i++){const p=locals[i],entry=document.createElement('div');entry.className='local-item'+(met.has(i)?'':' unmet');entry.innerHTML=`<i style="background:${met.has(i)?`#${p.coat.toString(16).padStart(6,'0')}`:'#4a544b'}">${met.has(i)?p.mark:'?'}</i><span><b>${met.has(i)?p.name:'Unknown neighbor'}</b><small>${met.has(i)?p.job:'Somewhere in the county'}</small></span>`;localsGrid.append(entry)}}paintProgress();
const nearby=document.querySelector('#nearby'),nearName=document.querySelector('#nearName'),nearType=document.querySelector('#nearType'),nearAction=nearby.querySelector('span');let activeSite=-1,activeLocal=-1;
function targetDistance(x,z){let best={kind:'',index:-1,distance:Infinity};for(let i=0;i<sites.length;i++){const d=siteDistance(sites[i],x,z);if(d<best.distance)best={kind:'site',index:i,distance:d}}for(let i=0;i<locals.length;i++){const a=localActors[i],d=Math.hypot(a.position.x-x,a.position.z-z);if(d<best.distance)best={kind:'local',index:i,distance:d}}return best.distance<(best.kind==='site'?7.2:3.3)?best:{kind:'',index:-1,distance:Infinity}}
let toastTimer;function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function recordSite(){if(activeSite<0)return;const s=sites[activeSite];if(found.has(activeSite)){toast(`${s.name} — already in your field guide.`);return}found.add(activeSite);localStorage.setItem('elsewhere-notes',JSON.stringify([...found]));paintProgress();toast(found.size===sites.length?`Atlas complete. You found all ${sites.length} places.`:`Field note recorded: ${s.name}`)}
const dialogue=document.querySelector('#dialogue'),dlgName=document.querySelector('#dlgName'),dlgRole=document.querySelector('#dlgRole'),dlgText=document.querySelector('#dlgText'),dlgPortrait=document.querySelector('#dlgPortrait'),dlgProgress=document.querySelector('#dlgProgress');let conversation=null;
function closeConversation(){dialogue.classList.remove('open');document.body.classList.remove('talking');conversation=null}
function showConversationPage(){if(!conversation)return;dlgText.textContent=conversation.pages[conversation.page];dlgProgress.textContent=`${conversation.page+1} / ${conversation.pages.length}`}
function advanceConversation(){if(!conversation)return;if(conversation.page+1<conversation.pages.length){conversation.page++;showConversationPage()}else closeConversation()}
function talkToLocal(i){const p=locals[i];if(!met.has(i)){met.add(i);leads.add(p.lead);localStorage.setItem('elsewhere-locals',JSON.stringify([...met]));localStorage.setItem('elsewhere-leads',JSON.stringify([...leads]));paintProgress();toast(`${p.name} shared a lead: ${sites[p.lead].name}`)}const start=(localVisits[i]||0)%p.lines.length;localVisits[i]=(localVisits[i]||0)+1;localStorage.setItem('elsewhere-local-visits',JSON.stringify(localVisits));const pages=Array.from({length:3},(_,n)=>p.lines[(start+n)%p.lines.length]);conversation={pages,page:0};dlgName.textContent=p.name;dlgRole.textContent=p.job;dlgPortrait.textContent=p.mark;dlgPortrait.style.background=`#${p.coat.toString(16).padStart(6,'0')}`;showConversationPage();dialogue.classList.add('open');document.body.classList.add('talking');nearby.classList.remove('show')}
function interact(){if(activeLocal>=0){talkToLocal(activeLocal);return}recordSite()}
function updateNearby(){if(dialogue.classList.contains('open'))return;const target=targetDistance(player.x,player.z),nextSite=target.kind==='site'?target.index:-1,nextLocal=target.kind==='local'?target.index:-1;if(nextSite===activeSite&&nextLocal===activeLocal)return;activeSite=nextSite;activeLocal=nextLocal;if(target.kind==='local'){const p=locals[activeLocal];nearName.textContent=p.name;nearType.textContent=`${met.has(activeLocal)?'LOCAL · '+p.job:'MEET A LOCAL · '+p.job}`;nearAction.innerHTML='Press <b>E</b> to talk';nearby.classList.add('show');return}if(target.kind==='site'){const s=sites[activeSite];nearName.textContent=s.name;nearType.textContent=`${s.icon}  ${s.type}`;nearAction.innerHTML=found.has(activeSite)?'Press <b>E</b> to review this note':'Press <b>E</b> to record this place';nearby.classList.add('show');return}nearby.classList.remove('show')}

